# step_02: find time-respecting paths from 303 to 1293 within [46296,48695] with max lag 600
window = (46296,48695)
start_node = 303
target_node = 1293
max_lag = 600

# build outgoing dict
out = {}
for u,v,t in events:
    if window[0] <= t <= window[1]:
        out.setdefault(u, []).append((t,v))
for u in out:
    out[u].sort()

starts = out.get(start_node, [])
print('step_02')
print('window', window)
print('outgoing_count_from_303_in_window:', len(starts))

# find paths using DFS, limit to 200 paths
paths = []
stack = []
for (t,v) in starts:
    path = [(start_node, v, t)]
    if v == target_node:
        paths.append(path)
    else:
        stack.append((v,t,path))

while stack and len(paths) < 200:
    cur, curt, path = stack.pop()
    lst = out.get(cur, [])
    if not lst:
        continue
    # iterate over lst and pick events with time > curt and <= curt+max_lag
    for (t2, v2) in lst:
        if t2 <= curt:
            continue
        if t2 - curt > max_lag:
            break
        newp = path + [(cur, v2, t2)]
        if v2 == target_node:
            paths.append(newp)
            if len(paths) >= 200:
                break
        else:
            stack.append((v2, t2, newp))

print('found_paths_count:', len(paths))
if paths:
    print('first_path_len:', len(paths[0]))
    for e in paths[0]:
        print(e)

# direct edge
direct_exists = any(v==target_node for (t,v) in starts)
print('direct_edge_303_to_1293_in_window:', direct_exists)

# also show times when 1293 received any message in window
target_recv_times = [t for (u,v,t) in events if v==target_node and window[0]<=t<=window[1]]
print('1293_receive_times_count_in_window:', len(target_recv_times))
if target_recv_times:
    print('1293_receive_times_sample:', target_recv_times[:10])

# print list of nodes on first path if exists
if paths:
    nodes = [paths[0][0][0]] + [e[1] for e in paths[0]]
    print('first_path_nodes_sequence:', nodes)
else:
    print('no_paths')

